1	package credit
2	
3	import (
4		"os"
5		"path/filepath"
6		"strings"
7		"testing"
8	)
9	
10	func buildRoundTripStore(t *testing.T) *Store {
11		t.Helper()
12		s := NewStore()
13		mustStudent(t, s, "s1")
14		mustStudent(t, s, "s2")
15		mustCourse(t, s, "c1", "数学", 4)
16		mustCourse(t, s, "c2", "物理", 3)
17		mustReq(t, s, "s1", "r1", "c1")
18		mustReq(t, s, "s1", "r2", "c2")
19		mustEnroll(t, s, "s1", "r1", "2024春", "e1")
20		mustEnroll(t, s, "s1", "r1", "2024秋", "e2")
21		if _, _, err := s.SubmitResult("s1", "e1", Failed); err != nil {
22			t.Fatal(err)
23		}
24		if _, _, err := s.SubmitResult("s1", "e2", Passed); err != nil {
25			t.Fatal(err)
26		}
27		// 被拒绝的免修也应留在历史中并持久化。
28		if w, _, err := s.ApplyWaiver("s1", "nope", "wbad", "依据"); err != nil || w.Status != WaiverRejected {
29			t.Fatalf("构造被拒绝免修失败：%+v %v", w, err)
30		}
31		if _, _, err := s.ApplyWaiver("s1", "r2", "w1", "竞赛获奖免修"); err != nil {
32			t.Fatal(err)
33		}
34		if _, _, err := s.RevokeWaiver("s1", "w1", "撤销测试"); err != nil {
35			t.Fatal(err)
36		}
37		if _, err := s.SetCourseOpen("c2", false); err != nil {
38			t.Fatal(err)
39		}
40		return s
41	}
42	
43	func TestSaveLoadRoundTrip(t *testing.T) {
44		dir := t.TempDir()
45		path := filepath.Join(dir, "records.json")
46	
47		s := buildRoundTripStore(t)
48		if err := s.Save(path); err != nil {
49			t.Fatalf("Save: %v", err)
50		}
51	
52		loaded, existed, err := Load(path)
53		if err != nil || !existed {
54			t.Fatalf("Load: existed=%v err=%v", existed, err)
55		}
56		if loaded.Student("s1") == nil || loaded.Student("s2") == nil {
57			t.Fatal("学生未正确恢复")
58		}
59		if c := loaded.Course("c2"); c == nil || c.Open {
60			t.Fatalf("课程停开状态未恢复：%+v", c)
61		}
62		if e := loaded.Enrollment("s1", "e1"); e == nil || e.Result != Failed {
63			t.Fatalf("修读结果未恢复：%+v", e)
64		}
65		if e := loaded.Enrollment("s1", "e2"); e == nil || e.Result != Passed {
66			t.Fatalf("通过结果未恢复：%+v", e)
67		}
68		if w := loaded.Waiver("s1", "w1"); w == nil || w.Status != WaiverRevoked ||
69			w.Basis != "竞赛获奖免修" || w.Reason != "撤销测试" {
70			t.Fatalf("撤销免修的依据与状态未恢复：%+v", w)
71		}
72		if w := loaded.Waiver("s1", "wbad"); w == nil || w.Status != WaiverRejected || w.Reason == "" {
73			t.Fatalf("被拒绝免修历史未恢复：%+v", w)
74		}
75	
76		// 核对结果应与保存前一致：r1 通过计 4 学分，r2 免修撤销且无修读未满足。
77		rep := loaded.CheckStudent("s1")
78		if rep.TotalCredits != 4 {
79			t.Fatalf("恢复后总学分应为 4，得到 %d", rep.TotalCredits)
80		}
81		if len(rep.Unmet) != 1 || rep.Unmet[0] != "r2" {
82			t.Fatalf("恢复后未满足要求应为 [r2]，得到 %v", rep.Unmet)
83		}
84		if len(rep.RevokedWaivers) != 1 || rep.RevokedWaivers[0] != "w1" {
85			t.Fatalf("已撤销免修列表应为 [w1]，得到 %v", rep.RevokedWaivers)
86		}
87		if len(rep.RejectedWaivers) != 1 {
88			t.Fatalf("被拒绝免修应保留 1 条，得到 %d", len(rep.RejectedWaivers))
89		}
90	
91		// 再保存一次，内容保持稳定（序号计数器恢复后继续正确分配）。
92		if _, _, err := loaded.SubmitResult("s2", "x", Passed); err == nil {
93			t.Fatal("不存在的修读应报错")
94		}
95		mustReq(t, loaded, "s2", "r9", "c1")
96		mustEnroll(t, loaded, "s2", "r9", "2025春", "e9")
97		if _, _, err := loaded.SubmitResult("s2", "e9", Passed); err != nil {
98			t.Fatalf("恢复后继续提交结果失败：%v", err)
99		}
100	}
101	
102	func TestLoadMissingStartsEmpty(t *testing.T) {
103		dir := t.TempDir()
104		path := filepath.Join(dir, "sub", "nope.json") // 目录也不存在
105		s, existed, err := Load(path)
106		if err != nil || existed || s == nil {
107			t.Fatalf("文件不存在应返回空记录且无错误：existed=%v err=%v", existed, err)
108		}
109		if len(s.Students()) != 0 {
110			t.Fatal("应为空记录")
111		}
112		// Save 应能创建缺失的目录层级之外的文件……这里目录不存在，
113		// Save 只创建同目录临时文件，因此先建目录再保存验证空记录可写。
114		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
115			t.Fatal(err)
116		}
117		if err := s.Save(path); err != nil {
118			t.Fatalf("空记录保存失败：%v", err)
119		}
120	}
121	
122	func TestLoadCorruptAndUnreadableNotOverwritten(t *testing.T) {
123		dir := t.TempDir()
124	
125		cases := map[string]string{
126			"非法JSON": "{ not json",
127			"空文件":    "",
128			"悬空学生引用": `{"version":1,"students":[{"id":"s1"}],"requirements":[` +
129				`{"id":"r1","student":"sX","course":"c1"}]}` +
130				"\n",
131			"学分为零": `{"version":1,"courses":[{"id":"c1","name":"数学","credit":0,"open":true}]}` + "\n",
132			"坏版本":  `{"version":99}` + "\n",
