// duplicateObjectName 扫描一段完整 JSON，返回最先发现的“同一对象内重复
// 字段”的名称；没有重复时 ok=false。语法错误不在此处理（调用方随后用
// Decoder 解析并按损坏拒绝），扫描器读到语法错误即停止，返回“未发现
// 重复”即可。
//
// Token() 返回的键名已是解码后的文字，因此 "credit" 与 "credit"
// 会按同一名称判重；检查的是对象键，字段值（依据、课程名称等字符串
// 内容）里出现什么文字都不参与判重。每个对象单独持有一份名称集合，
// 嵌套对象出栈即恢复，不同对象的同名字段互不影响。
func duplicateObjectName(r io.Reader) (string, bool) {
	dec := json.NewDecoder(r)
	// 每一层对象一份已见字段名集合；stack[depth] 在该深度是对象时非 nil。
	var stack []map[string]bool
	inObject := func() bool { return len(stack) > 0 && stack[len(stack)-1] != nil }
	expectKey := false // 对象的下一个字符串 token 是键名
	for {
		tok, err := dec.Token()
		if err != nil {
			// io.EOF 或语法错误：语法错误交给后续正式解析判定。
			return "", false
		}
		switch v := tok.(type) {
		case json.Delim:
			switch v {
			case '{':
				stack = append(stack, map[string]bool{})
				expectKey = true
			case '}':
				stack = stack[:len(stack)-1]
				expectKey = inObject()
			case '[':
				stack = append(stack, nil)
				expectKey = false
			case ']':
				stack = stack[:len(stack)-1]
				expectKey = inObject()
			}
		case string:
			if expectKey && inObject() {
				seen := stack[len(stack)-1]
				if seen[v] {
					return v, true
				}
				seen[v] = true
			}
			// 键之后跟值，值之后（同一对象内）才又是键：用 InputOffset
			// 无法直接区分，改由读下一个分隔符/键时判断，这里只需保证
			// 值字符串不会被当成键——Token 流中值字符串的 expectKey
			// 必然为 false；处理完键后将其置 false，对象内逗号后读入
			// 的下一个字符串如何识别为键，见 expectKeyNext 处理：
			// 键名 token 之后下一个 token 是值，值若是字符串则
			// expectKey=false；若是对象/数组则由分隔符分支重置；
			// 对象内下一个键前必有一个值 token，分隔符分支在对象
			// 闭合后才恢复 true，因此这里保持 false 即可，逗号本身
			// 不产生 token。
			expectKey = false
		default:
			// null / bool / 数字都是值。
			expectKey = false
		}
		// 对象内一个值读完后，下一个字符串 token（若有）必为键名。
		// Token 流不产生逗号，无法靠“读到逗号”切换；利用闭合分隔符
		// 之外的状态：值 token 出现后，只要仍停留在同一对象内，
		// 紧接着的字符串只可能是键。
		if tok == nil {
			continue
		}
		if _, isDelim := tok.(json.Delim); !isDelim && inObject() {
			expectKey = true
		}
	}
}

