// duplicateObjectName 扫描一段完整 JSON，返回最先发现的“同一对象内重复
// 字段”的名称；没有重复时 ok=false。语法错误不在此处理（调用方随后用
// Decoder 解析并按损坏拒绝），扫描器读到语法错误即停止，返回“未发现
// 重复”即可。
//
// Token() 返回的键名已是解码后的文字，因此 "credit" 与 "credit"
// 会按同一名称判重；检查的是对象键，字段值（依据、课程名称等字符串
// 内容）里出现什么文字都不参与判重。每个对象单独持有一份名称集合，
// 嵌套对象出栈即恢复，不同对象的同名字段互不影响。
func duplicateObjectName(r io.Reader) (string, bool) {
	dec := json.NewDecoder(r)
	// frame 描述一层容器：对象记录已见字段名并跟踪下一个字符串是否为键；
	// 数组没有键，两个字段都不用。
	type frame struct {
		isObject  bool
		expectKey bool
		seen      map[string]bool
	}
	var stack []*frame
	top := func() *frame {
		if len(stack) == 0 {
			return nil
		}
		return stack[len(stack)-1]
	}
	for {
		tok, err := dec.Token()
		if err != nil {
			// io.EOF 或语法错误：语法错误交给后续正式解析判定。
			return "", false
		}
		switch v := tok.(type) {
		case json.Delim:
			switch v {
			case '{':
				// 空对象的下一个字符串也是键。
				stack = append(stack, &frame{
					isObject:  true,
					expectKey: true,
					seen:      map[string]bool{},
				})
			case '[':
				stack = append(stack, &frame{})
			case '}', ']':
				stack = stack[:len(stack)-1]
				// 刚闭合的对象/数组本身是父对象的一个值，父对象接下来
				// 只能遇到闭合括号或新的键名。
				if p := top(); p != nil && p.isObject {
					p.expectKey = true
				}
			}
		case string:
			f := top()
			if f == nil || !f.isObject {
				continue // 数组中的字符串元素，与判重无关。
			}
			if f.expectKey {
				if f.seen[v] {
					return v, true
				}
				f.seen[v] = true
				f.expectKey = false // 键之后是值。
			} else {
				// 字符串本身作为值，值结束后下一个 token 只能是 } 或键。
				f.expectKey = true
			}
		default:
			// number / bool / null 作为值：父对象随后期待 } 或新键名。
			if f := top(); f != nil && f.isObject {
				f.expectKey = true
			}
		}
	}
}

