			// 键之后跟值，值之后（同一对象内）才又是键：用 InputOffset
			// 无法直接区分，改由读下一个分隔符/键时判断，这里只需保证
			// 值字符串不会被当成键——Token 流中值字符串的 expectKey
			// 必然为 false；处理完键后将其置 false，对象内逗号后读入
			// 的下一个字符串如何识别为键，见 expectKeyNext 处理：
			// 键名 token 之后下一个 token 是值，值若是字符串则
			// expectKey=false；若是对象/数组则由分隔符分支重置；
			// 对象内下一个键前必有一个值 token，分隔符分支在对象
			// 闭合后才恢复 true，因此这里保持 false 即可，逗号本身
			// 不产生 token。
			expectKey = false
		default:
			// null / bool / 数字都是值。
			expectKey = false
		}
		// 对象内一个值读完后，下一个字符串 token（若有）必为键名。
		// Token 流不产生逗号，无法靠“读到逗号”切换；利用闭合分隔符
		// 之外的状态：值 token 出现后，只要仍停留在同一对象内，
		// 紧接着的字符串只可能是键。
		if tok == nil {
			continue
		}
		if _, isDelim := tok.(json.Delim); !isDelim && inObject() {
			expectKey = true
		}
	}
}

